add_action( 'woocommerce_before_cart', 'perfectpixel_message_if_product_in_cart' );

/**
 * Whether the cart contains a product (or one of its variations).
 */
function perfectpixel_cart_has_product( $product_id ) {
	if ( ! WC()->cart ) {
		return false;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( (int) $item['product_id'] === (int) $product_id || (int) $item['variation_id'] === (int) $product_id ) {
			return true;
		}
	}
	return false;
}

function perfectpixel_message_if_product_in_cart() {
	$id = (int) '{{cart_product_id}}';
	if ( $id && perfectpixel_cart_has_product( $id ) ) {
		echo '<div class="woocommerce-info">' . wp_kses_post( '{{cart_product_message}}' ) . '</div>';
	}
}
